		for (int i = 0; i < a.length; i++) {
			int n = extractDigits(a[i], nthDig);	
			c[n - 1] += 1;
		}

		// cumulativa
		for (int i = 1; i <= c.length; i++)
			c[i] += c[i-1];

		int[] b = new int[a.length];
		for (int i = a.length - 1; i >= 0; i--) {
			int d = extractDigits(a[i], nthDig);

			b[c[d - 1] - 1] = a[i];
			c[d - 1] -= 1;
		}

		return b;
