public class RadixSort {

    public static int[] countingSort(int[] array, int exp) {
        int n = array.length;
        int[] output = new int[n];
        int[] count = new int[1000];

        // Inicializa o array de contagem
        Arrays.fill(count, 0);

        // Armazena a ocorrência dos números no array de contagem
        for (int i = 0; i < n; i++) {
            int index = (array[i] / exp) % 1000;
            count[index]++;
