            nums[k++] = Integer.parseInt(s);
        }

        int n = nums.length - 1;

        for (int i = parent(n); i >= 0; i--) {
           heapify(nums, i);
        }

        System.out.println(Arrays.toString(nums));
        sc.close();
    }

    static void heapify(int[] nums, int i) {

        int left = left(i);
        int right = right(i);
        int max = max(i, left, right, nums);


        if (max != i) {
            int tmp = nums[i];
            nums[i] = nums[max];
            nums[max] = tmp;
            heapify(nums, max);
        }

    }

