            int middle = (left + right) / 2;

            // Dividir a primeira metade
            mergeSort(left, middle);
            // Dividir a segunda metade
            mergeSort(middle + 1, right);

            // Mesclar as duas metades
            merge(left, middle, right);
        }
    }

    private void merge(int left, int middle, int right) {
        // Copiar ambos os lados para o array temporário
        for (int i = left; i <= right; i++) {
            tempArray[i] = array[i];
        }

        int i = left;
        int j = middle + 1;
        int k = left;

        // Mesclar os arrays temporários de volta ao array original
        while (i <= middle && j <= right) {
            if (tempArray[i] <= tempArray[j]) {
                array[k] = tempArray[i];
                i++;
            } else {
                array[k] = tempArray[j];
                j++;
            }
            k++;
        }

        // Copiar os elementos restantes do lado esquerdo, se houver
        while (i <= middle) {
            array[k] = tempArray[i];
            k++;
            i++;
        }

        // Não é necessário copiar os elementos restantes do lado direito, pois eles já estão no lugar certo

        // Imprimir o array após a mesclagem
        printArray(left, right);
    }

